  public getIdade(data: string): number {
    let nascimento = new Date(data);
    let diff = Date.now() - nascimento.getTime();
    let idadeDate = new Date(diff);
    return idadeDate.getUTCFullYear() - 1970;
  }

  public getIdadeBaseAnoHipico(data : string) : number {
    let dataNascimento = new Date(data);
    return this.calculoIdadeUsuarioComBaseAnoHipico(dataNascimento.getFullYear(),
    dataNascimento.getMonth(), dataNascimento.getDate());
  }

  public calculoIdadeUsuarioComBaseAnoHipico(year, month, day) {
    var now = new Date()	
    var age = now.getFullYear();
    var monthNow = now.getMonth();
    var dayNow = now.getDate();
    var control = false;

    if(monthNow < this.mesHipico){
      age -= 1;
    }

    if((month > this.mesHipico) || (month == this.mesHipico && day > this.diaHipico)){
      if((monthNow > month) || (monthNow == month && dayNow >= day)){
        age -= 1;
        control = true;
      }
    }

    let idade = age -  year;
    var mdif = this.mesHipico - (month + 1) //0=jan
    
    if(mdif < 0 && !control){
      --idade
    }else if(mdif == 0){
      var ddif = this.diaHipico - day
      if(ddif < 0){
        --idade
      }
    }

    return idade
  }


