  reduzTexto(texto, tamanho) {
    var textoReduzido = this.cortaTexto(texto, tamanho);
    if( texto && texto.length > tamanho) {
      textoReduzido += '...';
    }
    return textoReduzido;
  }

  cortaTexto(texto, tamanho) {
      if(texto && texto.length > tamanho) {
        return texto.substr(0, tamanho);
      } else {
        return texto;
      }
  }

  public irPara(router: Router, rota: string, parametros: any = null) {
      if (parametros) {
        router.navigate([rota], {
          queryParams : parametros
        });
      } else {
        router.navigate([rota]);
      }
      this.pilhaDeRotas.push({
        rota: rota,
        chamador: router.url,
        parametros: parametros ? parametros : []
      });
  }

  public voltarParaChamador(router: Router, padrao: any[]) {
    if (!this.isPilhaVazia()) {
      const desempilhado = this.pilhaDeRotas.pop();
      router.navigate([decodeURI(desempilhado.chamador)]);
    } else {
      router.navigate(padrao);
    }
  }

