  public maskTelefone(rawValue) {
    const numbers = rawValue.match(/\d/g);
    let numberLength = 0;
    if (numbers) {
        numberLength = numbers.join('').length;
    }
    if (numberLength <= 10) {
        return ['(', /\d/, /\d/, ')', ' ', /\d/, /\d/, /\d/, /\d/, '-', /\d/, /\d/, /\d/, /\d/];
    } else {
        return ['(', /\d/, /\d/, ')', ' ', /\d/, /\d/, /\d/, /\d/, /\d/, '-', /\d/, /\d/, /\d/, /\d/];
    }
  }

  public removeCharacter(str_to_remove: string, str:string) {
    let reg = new RegExp(str_to_remove);
    while(str.includes(str_to_remove)){
      str = str.replace(reg, '');
    }
    return str;
  }

  download(nome_arquivo, conteudo) {
    var element = document.createElement('a');
    element.setAttribute('href', 'data:text/xml;charset=utf-8,' + encodeURIComponent(conteudo));
    element.setAttribute('download', nome_arquivo);
  
    element.style.display = 'none';
    document.body.appendChild(element);
  
    element.click();
  
    document.body.removeChild(element);
  }

