  public getDataAgora() : string{
    let now = new Date();
    let data =  now.getFullYear() + '-' + (now.getMonth() + 1) + '-' + now.getDate();
    let hora = now.getHours() + ':' + now.getMinutes();
    return data + ' ' + hora;
  }

  public downloadExcel(titulos: string[], dados: any[], titulo: string){
    let csv = '<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">';
    csv += '<meta http-equiv="content-type" content="application/vnd.ms-excel; charset=UTF-8">';
    csv += '<style>';
    csv += '  table {border: 2px solid black;font-family:Calibri;font-size:9pt;color:black;margin: 2px;}';
    csv += '  th    {font-weight:900}';
    csv += '  td    {font-weight:300;}';
    csv += '  .text {ms-number-format:"\@";}';
    csv += '</style>';
    csv += '<body>';
    csv += '<table>';
    csv += '<thead s>';
    csv += '<tr>';
    titulos.forEach( col => {
      csv += '<th style="text-align:center; width:70;background-color:silver;border:1px solid black;">' + col.toUpperCase() + '</th>';
    });
    csv += '</tr>';
    csv += '</thead>';
    csv += '<tbody>';

    dados.forEach(dado => {
      csv += '<tr>';
      for (const key in dado) {
        csv += '<td style="text-align:center;border:1px solid black; width: 100;">'+ dado[key] +'</td>';
      }
      csv += '</tr>';
    })
    csv += '</tbody>';
    csv += '</table>';
    csv += '</body>';
    csv += '</html>';

    if (window.Blob) {
      var textFileAsBlob = new Blob([csv], {
          type: 'text/plain;charset=utf-8;'
      });
      var downloadLink = document.createElement("a");
      downloadLink.download = titulo;
      downloadLink.innerHTML = "Download File";
      if (window.URL != null) {
          // o chrome permite que o link seja clicado sem inserir ele no DOM (fisicamente na pagina)
          //downloadLink.href = window.webkitURL.createObjectURL(textFileAsBlob);
          downloadLink.href = window.URL.createObjectURL(textFileAsBlob);
      } else {
          // O Firefox não permite clicar no link se nao existir na pagina, por isso precisa da funca para
          // pagar o mesmo após ser clicado
          downloadLink.href           = window.URL.createObjectURL(textFileAsBlob);
          downloadLink.style.display  = "none";
          document.body.appendChild(downloadLink);
      }
      ////////////////////////////////////
      // IE salva o arquivo deste jeito //
      ////////////////////////////////////
      if (navigator.msSaveBlob) {
          navigator.msSaveBlob(textFileAsBlob, titulo);
      ////////////////////////////////////////////////////////////////////
      // Firefox e Chrome permitem clicar no link para salvar o arquivo //
      ////////////////////////////////////////////////////////////////////
      } else {
          downloadLink.click();
      }
    }
  }

  public preparaExcelCompetidorTrio(dados: any[]){
    let retorno = [];
    if(dados.length > 0){
      dados.forEach(dado => {
        if(dado.competidores.length > 0){
          dado.competidores.forEach((competidor, index) => {
            retorno.push({
              nomeProva: index == 0 ? dado.nome : '',
              nomeUm: competidor[0].nome,
              nomeDois: competidor[1].nome,
              nomeTres: competidor[2].nome,
              handicapUm: competidor[0].handicap,
              handicapDois: competidor[1].handicap,
              handicapTres: competidor[2].handicap,
              cavaloUm: competidor[0].cavalo,
              cavaloDois: competidor[1].cavalo,
              cavaloTres: competidor[2].cavalo,
            });
          });
        }
      });
    }
    return retorno;
  }

